args<-commandArgs(FALSE);here<-dirname(normalizePath(sub("^--file=","",args[grepl("^--file=",args)][1])))
source(file.path(here,"../../scripts/dendra/core.R"))
total<-0L
check<-function(name,expr){if(!isTRUE(expr))stop(name);total<<-total+1L;cat("PASS",name,"\n")}
s<-list(datastream_id="111111111111111111111111",unit_normalization=list(status="verified_percent_conversion",multiplier=1,offset=0),cadence_seconds=3600)
make_rows<-function(start="2024-02-28",days=1,values=10,step=3600) {
  t<-seq(as.numeric(parse_utc(paste0(start,"T08:00:00Z"))),length.out=days*86400/step,by=step)
  data.frame(t=format(as.POSIXct(t,origin="1970-01-01",tz="UTC"),"%Y-%m-%dT%H:%M:%SZ",tz="UTC"),datastream_id=s$datastream_id,v=rep(values,length.out=length(t)),value_status="number",duplicate_conflict=FALSE,alternative_out_of_range=FALSE,time=t,date=as.character(as.Date(as.POSIXct(t-28800,origin="1970-01-01",tz="UTC"),tz="UTC")))
}
x<-make_rows();ctx<-cadence_context(x,s,"fixture")
a<-function(x=x,stream=s,start="2024-02-28",end="2024-02-29",context=ctx,previous=NULL)aggregate_daily(x,stream,start,end,context,previous)
r<-a(x)$rows[[1]];check("hourly mean and coverage",r$mean_percent==10&&r$plot_eligible&&r$expected_samples==24)
z<-make_rows(values=0);check("real zero preserved",a(z)$rows[[1]]$mean_percent==0)
z<-x;z$v[1]<-NA;z$value_status[1]<-"null";r<-a(z)$rows[[1]];check("null excluded from sample count",r$n_null==1&&r$n_valid==23&&r$mean_percent==10)
z<-x;z$value_status[1]<-"missing";z$v[1]<-NA;check("missing is not zero",a(z)$rows[[1]]$n_missing==1)
z<-rbind(x,x[1,]);r<-a(z)$rows[[1]];check("identical duplicate",r$n_valid==24&&r$n_duplicate_rows==1&&r$plot_eligible)
z<-rbind(x,transform(x[1,],v=20));r<-a(z)$rows[[1]];check("conflicting duplicate excludes day",r$n_duplicate_conflicts==1&&!r$plot_eligible)
z<-x;z$v[2]<-101;r<-a(z)$rows[[1]];check("moisture range retained diagnostic",!r$plot_eligible&&r$n_out_of_range==1&&!is.null(r$mean_native))
z<-x[FALSE,];r<-a(z)$rows[[1]];check("empty day explicit",is.null(r$mean_percent)&&!r$plot_eligible&&r$n_total==0)
z<-x[1:10,];check("sparse day not eligible",!a(z)$rows[[1]]$plot_eligible)
z<-x;z$time[5]<-z$time[5]+10;check("off-grid cadence",!a(z)$rows[[1]]$plot_eligible)
z<-x[c(1:12,14,16,18,20,22,24),];check("within day cadence change",'possible_within_day_cadence_change' %in% a(z)$rows[[1]]$flags)
u<-s;u$unit_normalization<-list(status="unresolved");r<-a(x,u)$rows[[1]];check("unresolved scale held",!r$plot_eligible&&is.null(r$mean_percent)&&r$mean_native==10)
temp<-s;temp$parameter<-"soil_temperature";temp$unit_normalization<-list(status="verified_temperature_conversion",multiplier=1,offset=0);r<-a(make_rows(values=-5),temp)$rows[[1]];check("negative Celsius valid",r$plot_eligible&&r$mean_value== -5&&r$n_out_of_range==0)
temp$unit_normalization$multiplier<-5/9;temp$unit_normalization$offset<- -32*5/9;check("Fahrenheit conversion",abs(a(make_rows(values=14),temp)$rows[[1]]$mean_value+10)<1e-12)
check("leap actual/aligned calendar",a(make_rows(days=3),end="2024-03-02")$rows[[3]]$dowy==153)
check("nonleap aligned slot",a(make_rows(start="2025-03-01"),start="2025-03-01",end="2025-03-02")$rows[[1]]$water_day_aligned==153)
check("fixed cutoff before boundary",completed_cutoff("2026-09-20T07:59:59Z")=="2026-09-18")
check("fixed cutoff after boundary",completed_cutoff("2026-09-20T08:00:00Z")=="2026-09-19")
for(d in c("2024-03-10","2024-11-03"))check(paste("fixed DST day",d),a(make_rows(start=d),start=d,end=as.character(as.Date(d)+1))$rows[[1]]$n_total==24)
# Context and preceding observed cadence travel with partitions, including sparse tails.
x<-make_rows(start="2024-01-01",days=65);x<-x[!(x$date=="2024-02-01" & (seq_len(nrow(x))%%24)>2),];ctx<-cadence_context(x,s,"fixed-bootstrap")
whole<-aggregate_daily(x,s,"2024-01-01","2024-03-06",ctx)$rows;parts<-list();prev<-NULL
for(pair in list(c("2024-01-01","2024-02-01"),c("2024-02-01","2024-03-01"),c("2024-03-01","2024-03-06"))) {b<-aggregate_daily(x[x$date>=pair[1]&x$date<pair[2],],s,pair[1],pair[2],ctx,prev);parts<-c(parts,b$rows);prev<-b$previous_cadence}
check("monolithic versus monthly including sparse day",identical(whole,parts))
parts<-list();prev<-NULL
for(d in as.character(seq(as.Date("2024-01-01"),as.Date("2024-03-05"),by="day"))) {b<-aggregate_daily(x[x$date==d,],s,d,as.character(as.Date(d)+1),ctx,prev);parts<-c(parts,b$rows);prev<-b$previous_cadence}
check("one-day incremental with retained context",identical(whole,parts))
check("fallback unaffected by retained raw window",identical(aggregate_daily(x[x$date=="2024-02-01",],s,"2024-02-01","2024-02-02",ctx,3600)$rows,whole[32]))
rows<-lapply(seq_len(60),function(i) list(date=as.character(as.Date("2024-01-01")+i-1),plot_eligible=TRUE,mean_percent=if(i>30)10.5 else 10,n_valid=1,water_year=2024,dowy=i+92,water_day_aligned=i+92,expected_samples=1,coverage_fraction=1,temporal_span_fraction=1,flags=list()))
check("equal day weights inclusive deadband",recent_change(rows,"2024-02-29",30)$state=="little")
rows[[60]]$mean_percent<-11;check("wetting beyond deadband",recent_change(rows,"2024-02-29",30)$state=="wetting")
check("stale snapshot mean withheld",recent_change(rows,"2024-03-05",7)$state=="stale")
check("empty recent state",recent_change(list(),"2024-02-29",7)$state=="no-data")
rows[50:52]<-lapply(rows[50:52],function(r){r$plot_eligible<-FALSE;r});check("three day gap with adequate count",recent_change(rows,"2024-02-29",30)$state=="insufficient")
check("frozen mode never current",!feed_freshness("replay","2024-01-01T00:00:00Z","2024-01-01T00:00:00Z","2024-01-01T00:00:00Z")$current)
check("old retrieval cannot be refreshed by rebuild",!feed_freshness("live","2024-01-06T00:00:00Z","2024-01-06T00:00:00Z","2024-01-01T00:00:00Z","2024-01-06T00:00:00Z")$current)
cat("TOTAL",total,"checks passed\n")
small<-lapply(1:3,function(i)list(date=as.character(as.Date('2024-01-01')+i-1),plot_eligible=TRUE,n_total=24))
empty<-list(list(date='2024-01-02',plot_eligible=FALSE,n_total=0));replaced<-replace_daily_interval(small,empty,'2024-01-02','2024-01-03')
check('complete empty removes prior observations',replaced[[2]]$n_total==0&&replaced[[1]]$n_total==24&&replaced[[3]]$n_total==24)
large<-lapply(1:20,function(i)list(date=as.character(as.Date('2024-01-01')+i-1),plot_eligible=TRUE,n_total=24))
check('suspicious widespread empty guarded',inherits(try(replace_daily_interval(large,list(),'2024-01-01','2024-01-21'),silent=TRUE),'try-error'))
cat('FINAL TOTAL',total,'checks passed\n')
z<-make_rows();z<-rbind(z,z[1,]);check('runner normalization remains idempotent',identical(aggregate_daily(z,s,'2024-02-28','2024-02-29',ctx)$rows,aggregate_daily(normalize_native(z,s),s,'2024-02-28','2024-02-29',ctx)$rows))
cat('FINAL TOTAL',total,'checks passed\n')
